import{_ as r,c as d,o,at as e}from"./chunks/framework.mXguc-v6.js";const f=JSON.parse('{"title":"Vue3 术语速查","description":"","frontmatter":{},"headers":[],"relativePath":"views/interview/frontend/vue/glossary.md","filePath":"views/interview/frontend/vue/glossary.md","lastUpdated":null}'),s={name:"views/interview/frontend/vue/glossary.md"};function n(a,t,g,i,l,p){return o(),d("div",null,t[0]||(t[0]=[e('<h1 id="vue3-术语速查" tabindex="-1">Vue3 术语速查 <a class="header-anchor" href="#vue3-术语速查" aria-label="Permalink to &quot;Vue3 术语速查&quot;">​</a></h1><table tabindex="0"><thead><tr><th>术语</th><th>一句话</th></tr></thead><tbody><tr><td><strong>Proxy</strong></td><td>ES6 内置，Vue3 用它代理整个对象，替代 defineProperty</td></tr><tr><td><strong>ref</strong></td><td>包装基本类型为响应式对象，模板自动解包</td></tr><tr><td><strong>reactive</strong></td><td>直接代理对象，深层响应</td></tr><tr><td><strong>computed</strong></td><td>派生新值，懒计算 + 缓存</td></tr><tr><td><strong>watch</strong></td><td>监听响应式源变化，可拿到 oldValue</td></tr><tr><td><strong>watchEffect</strong></td><td>自动追踪内部依赖，立即执行</td></tr><tr><td><strong>Composition API</strong></td><td>用 ref/computed/watch 组合逻辑，取代 Options API</td></tr><tr><td><strong>Options API</strong></td><td>Vue2 风格，data/computed/methods 分开写</td></tr><tr><td><strong>SFC</strong></td><td>.vue 单文件组件</td></tr><tr><td><strong>Vapor Mode</strong></td><td>无虚拟 DOM，编译器直接生成 DOM 更新代码</td></tr><tr><td><strong>PatchFlags</strong></td><td>编译时标记动态节点，diff 只检查有 flag 的部分</td></tr><tr><td><strong>Block Tree</strong></td><td>区块树，只追踪动态节点</td></tr><tr><td><strong>Static Hoisting</strong></td><td>静态节点提到 render 外面，只创建一次</td></tr><tr><td><strong>Template Compilation</strong></td><td>模板编译为渲染函数</td></tr><tr><td><strong>Effect System</strong></td><td>track 收集依赖，trigger 触发更新</td></tr><tr><td><strong>script setup</strong></td><td>语法糖，顶层变量直接在模板用</td></tr><tr><td><strong>defineProps</strong></td><td>定义 props，支持 TS 泛型</td></tr><tr><td><strong>defineEmits</strong></td><td>定义事件，支持 TS 约束</td></tr><tr><td><strong>defineModel</strong></td><td>v-model 语法糖，展开为 prop + emit</td></tr><tr><td><strong>v-model</strong></td><td>双向绑定指令</td></tr><tr><td><strong>v-for</strong></td><td>列表渲染</td></tr><tr><td><strong>v-if / v-show</strong></td><td>条件渲染——v-if 增删 DOM，v-show 切换 display</td></tr></tbody></table>',2)]))}const u=r(s,[["render",n]]);export{f as __pageData,u as default};
